repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('town', 34), ('united', 16), ('town', 7), ('united', 26), ('city', 17), ('town', 36), ('rovers', 46)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.reserve.py:
"""A pool of fixtures with a remembered total."""


class FixturePool:
    def __init__(self):
        self._fixtures = []
        self._total = None

    def add(self, fixture):
        """Add one fixture to the pool."""
        self._fixtures.append(fixture)
        self._total = None

    def remove(self, fixture):
        """Take one fixture out of the pool."""
        self._fixtures.remove(fixture)

    def total(self):
        """Return the total goals of the fixtures in the pool."""
        if self._total is None:
            self._total = sum(x.goals for x in self._fixtures)
        return self._total


def largest_goals(fixtures):
    """Return the largest goals, or None when there are no fixtures."""
    values = [x.goals for x in fixtures]
    return max(values) if values else None


def describe_fixture(fixture):
    """Return a one-line description of a fixture."""
    return "%s: %s" % (fixture.club, fixture.goals)
